import sys

data = sys.stdin.read().split()
r, c, S = int(data[0]), int(data[1]), int(data[2])
vals = list(map(int, data[3:]))
G = [[[vals[g * r * c + i * c + j] for j in range(c)] for i in range(r)] for g in range(2)]

def go(i, j, g):
    if i == r - 1 and j == c - 1:
        return 0
    best = None
    for di, dj in ((0, 1), (1, 0)):
        ni, nj = i + di, j + dj
        if ni < r and nj < c:
            for ng in (0, 1):
                cost = G[ng][ni][nj] + (S if ng != g else 0) + go(ni, nj, ng)
                if best is None or cost < best:
                    best = cost
    return best

print(G[0][0][0] + go(0, 0, 0))

